mapper.insert:
insert into STUDENT(
	SCHOOL_CODE, NAME, GRADE, SEMESTER, TRACK
) VALUES (
	#{schoolCode}, #{name}, #{grade}, #{semester}, #{track}
)

mapper.update:
update STUDENT
set
	NAME = #{name}
	,GRADE = #{grade}
	,SEMESTER = #{semester}
	,TRACK = #{track}
	,SCHOOL_CODE = #{schoolCode}
where STUDENT_NO = #{studentNo}

update STUDENT
set STATUS = #{status}
where STUDENT_NO = #{studentNo}
